result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "mlp.py", "content": """"Two-layer MLP (2-8-1) in pure numpy.

Architecture: 2 inputs -> 8 hidden units (tanh) -> 1 output unit (sigmoid).
Loss: binary cross-entropy. Training: full-batch gradient descent.
Weights initialized N(0, 0.5) with seed 0.
"""

import numpy as np


def sigmoid(z):
    return 1.0 / (1.0 + np.exp(-z))


def binary_cross_entropy(y_pred, y_true):
    """Mean BCE loss, clipped for numerical stability."""
    eps = 1e-12
    p = np.clip(y_pred, eps, 1.0 - eps)
    return -np.mean(y_true * np.log(p) + (1.0 - y_true) * np.log(1.0 - p))


class MLP:
    def __init__(self, n_in=2, n_hidden=8, n_out=1, seed=0):
        rng = np.random.default_rng(seed)
        self.W1 = rng.normal(0.0, 0.5, size=(n_in, n_hidden))
        self.b1 = rng.normal(0.0, 0.5, size=(n_hidden,))
        self.W2 = rng.normal(0.0, 0.5, size=(n_hidden, n_out))
        self.b2 = rng.normal(0.0, 0.5, size=(n_out,))
        # Caches filled by forward()
        self._cache = {}

    def params(self):
        return {
            "W1": self.W1,
            "b1": self.b1,
            "W2": self.W2,
            "b2": self.b2,
        }

    def forward(self, X):
        z1 = X @ self.W1 + self.b1
        h = np.tanh(z1)
        z2 = h @ self.W2 + self.b2
        y = sigmoid(z2)
        self._cache = {"X": X, "z1": z1, "h": h, "z2": z2, "y": y}
        return y

    def loss(self, X, Y):
        return binary_cross_entropy(self.forward(X), Y)

    def backward(self, Y):
        """Backprop through mean BCE loss. Returns grads dict matching params()."""
        cache = self._cache
        X, h, y = cache["X"], cache["h"], cache["y"]

        n = X.shape[0]
        eps = 1e-12
        p = np.clip(y, eps, 1.0 - eps)

        # dL/dz2 for sigmoid + mean-BCE simplifies to (p - y) / n
        dz2 = (p - Y) / n                       # (n, 1)
        gW2 = h.T @ dz2                         # (8, 1)
        gb2 = dz2.sum(axis=0)                   # (1,)

        dh = dz2 @ self.W2.T                    # (n, 8)
        dz1 = dh * (1.0 - np.tanh(cache["z1"]) ** 2)
        gW1 = X.T @ dz1                         # (2, 8)
        gb1 = dz1.sum(axis=0)                   # (8,)

        return {"W1": gW1, "b1": gb1, "W2": gW2, "b2": gb2}

    def train_step(self, X, Y, lr=0.5):
        self.forward(X)
        grads = self.backward(Y)
        for name in self.params():
            arr = getattr(self, name)
            arr -= lr * grads[name]
        return binary_cross_entropy(self._cache["y"], Y)
